mapper.select:
select
recycle.*
from recycle recycle

    and recycle.id = #{id}
    and recycle.nick_name like concat('%',#{nickName},'%')
    and recycle.recycle_sex = #{recycleSex}
    and recycle.recycle_age = #{recycleAge}
    and recycle.avatar = #{avatar}
    and recycle.tel like concat('%',#{tel},'%')
    and recycle.status = #{status}
    and recycle.account = #{account}
    and recycle.pwd = #{pwd}
    and recycle.create_time = #{createTime}


    limit #{current},#{pageSize}

select count(*) from recycle recycle

    and recycle.id = #{id}
    and recycle.nick_name like concat('%',#{nickName},'%')
    and recycle.recycle_sex = #{recycleSex}
    and recycle.recycle_age = #{recycleAge}
    and recycle.avatar = #{avatar}
    and recycle.tel like concat('%',#{tel},'%')
    and recycle.status = #{status}
    and recycle.account = #{account}
    and recycle.pwd = #{pwd}
    and recycle.create_time = #{createTime}
